  --focus:           var(--focus-ring);                  /* #305A85 / #4587A7            */
  /* brand + button intents */
  --accent:          var(--primary-background-default);  /* #DB0011                      */
  --pri:             var(--primary-background-default);
  --pri-hover:       var(--primary-background-hover);
  --pri-pressed:     var(--primary-background-pressed);
  --pri-disabled:    var(--primary-background-disabled);
