/* shape — semantic radius tier (ADR-0010 flex slots): the chip binds the CONTROL role. */
:where(.cn-tags) h2{font-size:12px; /* sentence case — type26-019 sweep (Dave ruling 2026-07-02): no uppercase, caps tracking removed with it */ margin:1.5rem 0 .8rem;}
:where(.cn-tags) .row{display:flex; gap:12px; flex-wrap:wrap; align-items:center;}
/* em-based chip — every dimension tracks the label font-size (scales with type) */
:where(.cn-tags) .tag{display:inline-flex; align-items:center; gap:.46em; height:2.15em; padding:0 .77em; border:1px solid var(--border); border-radius:var(--border-radius-control); /* CONTROL role — Mono square */
    background:transparent; color:var(--text); font:400 14px/1 var(--font); max-width:100%; white-space:nowrap; overflow:hidden;
    transition:max-width var(--ease), opacity var(--ease), margin var(--ease), padding var(--ease), border-width var(--ease), background 140ms ease, transform 150ms cubic-bezier(.4,0,.2,1);}
/* label overflow:VISIBLE (was hidden) — keeps cap/alphabetic icon alignment AND stops descenders
     being clipped; the chip's own overflow:hidden bounds length. See _DS-IMPROVEMENTS ds-005. */
:where(.cn-tags) .tag .lbl{overflow:visible; min-width:0;}
/* ---- VARIANTS (2026-07-18) — 3 styles × 2 sizes. Base .tag = bordered; +.x child = dismissible. ---- */
:where(.cn-tags) .tag--sm{font-size:12px;}
/* size — em-based, scales the whole chip */
:where(.cn-tags) .tag--plain{border-color:transparent; padding-inline:0;}
/* text only, no border */
:where(.cn-tags) .tag.link{cursor:pointer; text-decoration:none;}
:where(.cn-tags) .tag.link:hover{background:var(--hover); transform:scale(1.05);}
/* attract — echoes the button */
