:where(.cn-status-indicator) .stat.is-disabled .dot{background:var(--disabled);}
/* ---- form B: tint chip (INDICATOR radius role — Mono square; label is text/default → all tints AA) ---- */
:where(.cn-status-indicator) .chips{display:flex; flex-wrap:wrap; gap:12px;}
:where(.cn-status-indicator) .chip{display:inline-flex; align-items:center; gap:8px; height:24px; padding:0 8px; border-radius:var(--border-radius-indicator); /* type: t-cm-legal + .t-cm-slot (bound in canon/type.css - T-D9/T-D12) */ color:var(--label); white-space:nowrap;}
/* SAME spec as List-items .status — this atom IS that badge (both bind the indicator role) */
:where(.cn-status-indicator) .chip .dot{width:8px; height:8px;}
