:where(.cn-status-indicator) .sbar.ok{--edge:var(--success);}
:where(.cn-status-indicator) .sbar.warn{--edge:var(--warning);}
:where(.cn-status-indicator) .sbar.err{--edge:var(--error);}
:where(.cn-status-indicator) .sbar.inf{--edge:var(--info);}
:where(.cn-status-indicator) .sbar.neu{--edge:var(--neutral);}
