:where(.cn-status-indicator) .sim{/* type: t-cm-caption (bound in canon/type.css - T-D9/T-D12) */ padding:8px 16px; border:1px solid var(--neutral); background:transparent; color:var(--label); cursor:pointer; border-radius:var(--border-radius-control);}
:where(.cn-status-indicator) .sim:hover{border-color:var(--label);}
:where(.cn-status-indicator) .sim:active{transform:translateY(1px);}
:where(.cn-status-indicator) .sim:focus-visible{outline:2px solid var(--focus); outline-offset:2px;}
